\definecolor{plate}{HTML}{1F1F1F}
\definecolor{ink}{HTML}{F6F8FA}
\definecolor{acc1}{HTML}{7FB3FF}
\definecolor{acc2}{HTML}{7FE0B0}
\definecolor{acc3}{HTML}{FFB37F}
\definecolor{mid}{HTML}{9AA0A6}
\fill[plate] (-0.7,-3.3) rectangle (11.7,5.2);
\foreach \x in {0,1,...,11}{ \draw[mid!35!plate] (\x,-3.1) -- (\x,5.0); }
\foreach \y in {-3,-2,...,5}{ \draw[mid!35!plate] (-0.5,\y) -- (11.5,\y); }
\node[text=ink, font=\bfseries\large] at (5.5,4.6) {Plate-backed, both themes};
\foreach \i/\lbl/\c in {0/Accept/acc1, 1/Verify/acc2, 2/Emit/acc3}{
  \node[draw=\c, line width=1pt, fill=plate, text=ink, minimum width=2.6cm,
        minimum height=1.2cm, font=\small] (q\i) at (\i*3.6+1.6, 3.0) {\lbl};
}
\draw[-Stealth, draw=acc1, line width=1pt] (q0) -- (q1);
\draw[-Stealth, draw=acc2, line width=1pt] (q1) -- (q2);
\draw[-Stealth, draw=acc3, dashed, line width=1pt] (q2) to[bend right=30] (q0);
\draw[acc1, line width=1.2pt] plot[smooth] coordinates {(0.5,0.2) (3,1.5) (5.5,0.6) (8,1.8) (11,1.0)};
\draw[acc2, line width=1.2pt] plot[smooth] coordinates {(0.5,1.4) (3,0.4) (5.5,1.7) (8,0.7) (11,1.9)};
\foreach \k in {0,...,10}{ \fill[acc3] (\k+0.5, {0.9+0.5*sin(mod(\k*47,360))}) circle (2pt); }
\draw[ink, thick] (0.3,-0.3) -- (11.2,-0.3);
\foreach \k in {0,...,10}{ \node[text=ink, font=\tiny, below] at (\k+0.5,-0.35) {s\k}; }
\node[text=ink, font=\small] at (5.5,-1.4) {ink \#F6F8FA on plate \#1F1F1F, accents pastel};
\node[text=plate, fill=acc2, font=\small, inner sep=2pt] at (5.5,-2.3) {inverted chip on light accent};
\node[text=mid, font=\tiny] at (5.5,-2.9) {mid-grey \#9AA0A6 secondary text};
